/* feedback sheet */
.fb-bar{display:flex;align-items:center;justify-content:space-between;padding:6px 10px 6px 16px;border-top:1px solid var(--line)}
.fb-form{display:flex;flex-direction:column;gap:10px;padding:14px 16px 16px;border-top:1px solid var(--line)}
.fb-chips{display:flex;flex-wrap:wrap;gap:6px}
.fb-ta{width:100%;resize:none;background:transparent;border:1px solid var(--line);color:var(--text);font:inherit;font-size:13px;padding:8px 10px;outline:0;transition:border-color .25s}
.fb-ta:focus{border-color:var(--icon-line)}
.fb-actions{display:flex;justify-content:flex-end;gap:8px}
.fb-actions .btn{padding:8px 14px;font-size:13px}
.fb-thx{display:flex;align-items:center;gap:10px;padding:14px 16px;border-top:1px solid var(--line);font-size:13px;color:var(--text-dim)}

/* ---------- feedback sheet ---------- */
{
  const fb = $('#fb'), fold = $('#fb-fold'), thanks = $('#fb-thanks'), submit = $('#fb-submit'), chips = $('#fb-chips');
  const rate = r => $$('#fb [data-r]').forEach(b => b.classList.toggle('on', b.dataset.r === r));
  $$('#fb [data-r]').forEach(b => b.addEventListener('click', () => {
    const r = b.dataset.r; rate(r); thanks.classList.remove('open');
    if (r === 'up'){ fold.classList.remove('open'); $('#fb-thx-t').textContent = 'Thanks, glad it helped.'; setTimeout(() => thanks.classList.add('open'), 150); Sound.play('done'); }
    else { fold.classList.add('open'); Sound.play('open'); }
  }));
  chips.addEventListener('click', e => { const c = e.target.closest('.fchip'); if (!c) return; c.classList.toggle('on'); submit.disabled = !$('.fchip.on', chips); Sound.play('tick'); });
  $('#fb-cancel').addEventListener('click', () => { fold.classList.remove('open'); rate(null); Sound.play('close'); });
  submit.addEventListener('click', () => {
    fold.classList.remove('open'); $('#fb-thx-t').textContent = 'Thanks, this helps the agent improve.';
    setTimeout(() => { thanks.classList.add('open'); $$('.fchip', chips).forEach(c => c.classList.remove('on')); $('#fb-ta').value = ''; submit.disabled = true; }, 200);
    Sound.play('done');
  });
}
